// Inspect the actual cascade and browser input modality on the page generated by bloom.
const assert = require("node:assert/strict");
const { chromium } = require("playwright-core");

async function run() {
  const browser = await chromium.launch({ executablePath: process.argv[2] });
  try {
    const page = await browser.newPage();
    await page.goto(process.argv[3]);
    const style = (id, key) => page.locator("#" + id).evaluate((el, k) => getComputedStyle(el)[k], key);
    const kinds = ["box", "text", "input", "button"];
    const scopedBg = ["rgba(0, 0, 0, 0)", "rgba(0, 0, 0, 0)", "rgb(224, 240, 248)", "rgb(144, 64, 32)"];
    const primary = "rgb(48, 96, 144)";
    const green = "rgb(36, 104, 36)";
    const brown = "rgb(101, 67, 33)";
    assert.equal(await style("page-button", "backgroundColor"), "rgb(16, 32, 48)");
    assert.equal(await style("page-input", "backgroundColor"), "rgb(254, 254, 254)");
    assert.equal(await style("nested-text", "backgroundColor"), "rgba(0, 0, 0, 0)");
    assert.equal(await style("nested-text", "color"), "rgb(255, 0, 17)");

    for (const [i, kind] of kinds.entries()) {
      if (kind !== "button") assert.equal(await style("scope-" + kind, "color"), "rgb(38, 55, 71)");
      for (const [name, bg, padding] of [
        ["scope", scopedBg[i], ["0px", "0px", "4px 8px", "2px 8px"][i]],
        ["short", primary, "19px"],
        ["class", green, "7px"],
        ["both", green, "19px"],
        ["explicit", brown, "3px"],
      ]) {
        const id = name + "-" + kind;
        assert.equal(await style(id, "backgroundColor"), bg, id);
        assert.equal(await style(id, "padding"), padding, id);
        await page.locator("#" + id).hover();
        const hoverBg = await style(id, "backgroundColor");
        if (kind === "button" && (name === "scope" || name === "short")) {
          assert.notEqual(hoverBg, bg, id);
          assert.notEqual(hoverBg, "rgba(0, 0, 0, 0)", id);
        } else {
          assert.equal(hoverBg, bg, id);
        }
        if (kind === "input") {
          const expectedBorder = name === "scope" || name === "short" ? "rgb(0, 136, 85)" : "rgb(23, 38, 53)";
          assert.equal(await style(id, "borderTopColor"), expectedBorder, id);
        }
        await page.mouse.move(0, 0);
      }
    }
    await page.locator("#disabled").hover();
    assert.equal(await style("disabled", "backgroundColor"), scopedBg[3]);
    await page.mouse.move(0, 0);

    // Plain Box and Text stay out of the tab order. Each enabled control receives real keyboard focus.
    for (const name of ["page", "scope", "short", "class", "both", "explicit"]) {
      for (const kind of ["input", "button"]) {
        const id = name + "-" + kind;
        const normalBg = await style(id, "backgroundColor");
        await page.keyboard.press("Tab");
        assert.equal(await page.locator(":focus-visible").getAttribute("id"), id);
        assert.equal(await style(id, "backgroundColor"), normalBg, id);
        if (name !== "page") {
          const width = kind === "input" ? 2 : 4;
          assert.equal(await style(id, "boxShadow"), `rgb(0, 136, 85) 0px 0px 0px ${width}px`, id);
        }
        if (name === "short" && kind === "button") {
          const ring = await style(id, "boxShadow");
          await page.locator("#" + id).hover();
          assert.notEqual(await style(id, "backgroundColor"), normalBg);
          assert.equal(await style(id, "boxShadow"), ring);
          await page.mouse.move(0, 0);
        }
        if (["class", "both", "explicit"].includes(name)) {
          assert.equal(await style(id, "outlineStyle"), "dotted", id);
          assert.equal(await style(id, "borderRadius"), "13px", id);
        }
      }
    }
    for (const id of ["tab-box", "tab-text"]) {
      await page.keyboard.press("Tab");
      assert.equal(await page.locator(":focus-visible").getAttribute("id"), id);
      assert.equal(await style(id, "outlineColor"), "rgb(0, 136, 85)");
      assert.equal(await style(id, "outlineStyle"), "solid");
    }
    assert.equal(await style("divider", "width"), "37px");
    assert.equal(await style("divider", "borderTopColor"), "rgb(0, 136, 85)");
    assert.equal(await style("desktop-stack", "display"), "flex");
    assert.equal(await style("desktop-stack", "flexDirection"), "row");
    assert.equal(await style("responsive-stack", "display"), "flex");
    assert.equal(await style("responsive-stack", "flexDirection"), "column");
    await page.setViewportSize({ width: 480, height: 800 });
    assert.equal(await style("desktop-stack", "display"), "none");
    assert.equal(await style("responsive-stack", "flexDirection"), "row");
    assert.equal(await style("explicit-stack", "display"), "grid");
  } finally {
    await browser.close();
  }
}

run().catch(error => { console.error(error); process.exitCode = 1; });
